/* ---------- Turquie régionale, Levant, Golfe, Caucase et Asie centrale ---------- */
const D51 = [
{ id:'ali-nazik', c:'as', lat:37.066, lon:37.378, base:4, prep:35, cook:30, diff:2, tags:['lamb','grill','comfort'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'grill',food:['#f0e8d0','#8f5a3a','#c9402c','#e8dcc0'],garnish:'#7fae6a'},
  n:{fr:'Ali Nazik',en:'Ali Nazik'},
  p:{fr:'Gaziantep, Turquie',en:'Gaziantep, Turkey'},
  d:{fr:"Une purée d'aubergines fumées au yaourt et à l'ail, couronnée d'agneau haché au couteau. La légende dit que le sultan Selim, servi à Gaziantep, demanda quelle main douce avait fait cela : « eli nazik ».",
     en:"A purée of smoked aubergine with yogurt and garlic, crowned with knife-chopped lamb. Legend says Sultan Selim, served in Gaziantep, asked whose gentle hand had made it: 'eli nazik'."},
  i:[['eggplant',1.2,'kg'],['plain_yogurt',400,'g'],['garlic',6,'clove'],['lamb_shoulder',600,'g'],['lamb_fat',80,'g'],['butter',80,'g'],['aleppo_pepper',2,'tsp'],['tomato_paste',1,'tbsp'],['ripe_tomato',200,'g'],['pita_bread',4,'pc'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Grillez les aubergines entières directement sur la flamme jusqu'à ce que la peau soit noire et que la chair s'affaisse.","Laissez-les tiédir dans un sac, pelez-les et laissez-les égoutter 20 minutes : l'eau amère doit partir.","Écrasez la chair à la fourchette avec le yaourt et l'ail pilé, et gardez tiède au bain-marie — jamais sur le feu direct.","Hachez l'agneau et le gras au couteau, saisissez-les à feu vif sans les remuer, ajoutez le concentré et la tomate.","Étalez la purée dans le plat, creusez un puits, versez la viande et arrosez de beurre fondu au piment d'Alep."],
     en:["Char the whole aubergines directly over a flame until the skin is black and the flesh collapses.","Let them steam in a bag, peel them and drain them for 20 minutes: the bitter water must go.","Mash the flesh with a fork with the yogurt and pounded garlic, and keep it warm over a bain-marie — never direct heat.","Chop the lamb and fat by knife, sear them over high heat without stirring, add the tomato paste and tomato.","Spread the purée in the dish, hollow a well, spoon in the meat and pour over butter melted with Aleppo pepper."]} },

{ id:'perde-pilav', c:'as', lat:37.759, lon:38.277, base:6, prep:60, cook:60, diff:3, tags:['rice','festive','poultry'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#c9924a','#f2dfa8','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Perde pilav',en:'Perde pilav'},
  p:{fr:'Siirt, Turquie',en:'Siirt, Turkey'},
  d:{fr:"Un pilaf de poulet, d'amandes et de raisins enfermé dans une croûte de pâte dorée en forme de dôme. On le servait aux jeunes mariés : le rideau de pâte symbolise le foyer, les amandes les enfants à venir.",
     en:"A pilaf of chicken, almonds and currants sealed in a golden dome of pastry. It was served to newlyweds: the curtain of dough stands for the home, the almonds for children to come."},
  i:[['flour',500,'g'],['butter',250,'g'],['egg',3,'pc'],['plain_yogurt',150,'g'],['baking_powder',1,'tsp'],['basmati_rice',400,'g'],['chicken',800,'g'],['almonds',120,'g'],['currants',100,'g'],['pistachios',80,'g'],['allspice',1,'tsp'],['cinnamon',1,'tsp'],['chicken_broth',700,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pochez le poulet 40 minutes ; désossez-le, taillez-le en dés et gardez le bouillon.","Faites revenir les amandes mondées et les pistaches au beurre, ajoutez le riz rincé, puis le bouillon, les raisins et les épices. Cuisez 15 minutes et laissez tiédir.","Pétrissez farine, beurre, œufs, yaourt et levure en une pâte souple ; laissez-la reposer 30 minutes.","Beurrez un moule à bords hauts, chemisez-le de pâte étalée à 5 mm en laissant retomber les bords.","Remplissez de pilaf bien tassé, rabattez la pâte, dorez à l'œuf et enfournez 45 minutes à 180 °C. Démoulez chaud, d'un seul geste."],
     en:["Poach the chicken for 40 minutes; bone it, dice it and keep the stock.","Fry the blanched almonds and pistachios in butter, add the rinsed rice, then the stock, currants and spices. Cook for 15 minutes and let it cool.","Knead the flour, butter, eggs, yogurt and baking powder into a supple dough; rest it for 30 minutes.","Butter a deep mould and line it with dough rolled to 5 mm, leaving the edges hanging.","Fill with the pilaf, well packed, fold the dough over, glaze with egg and bake for 45 minutes at 180°C. Turn it out hot, in one movement."]} },

{ id:'manti-kayseri', c:'as', lat:38.734, lon:35.478, base:4, prep:120, cook:20, diff:3, tags:['lamb','comfort','festive'],
  art:{v:'bowl',bg:'#33251c',plate:'#f4ecd8',style:'pastry',food:['#f0e8d0','#e8dcb8','#c9402c','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Mantı de Kayseri',en:'Kayseri mantı'},
  p:{fr:'Kayseri, Turquie',en:'Kayseri, Turkey'},
  d:{fr:"Des raviolis minuscules à l'agneau, servis sous un yaourt à l'ail et un beurre au piment. À Kayseri, on dit qu'une bonne belle-fille en fait tenir quarante dans une cuillère : la taille est un examen de passage.",
     en:"Minuscule lamb dumplings served under garlic yogurt and chilli butter. In Kayseri they say a good daughter-in-law fits forty on one spoon: the size is an examination."},
  i:[['flour',400,'g'],['egg',2,'pc'],['water',150,'ml'],['lamb_shoulder',400,'g'],['onion',1,'pc'],['parsley',3,'tbsp'],['plain_yogurt',600,'g'],['garlic',6,'clove'],['butter',120,'g'],['aleppo_pepper',2,'tsp'],['dried_mint',1,'tbsp'],['sumac',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez la farine, les œufs, l'eau et le sel 15 minutes en une pâte très ferme, et laissez-la reposer une heure.","Hachez l'agneau avec l'oignon et le persil, salez et poivrez généreusement.","Étalez la pâte au rouleau jusqu'à voir le bois de la table à travers, puis découpez des carrés de 2 cm.","Déposez sur chacun une pointe de farce grosse comme un grain de riz, et pincez les quatre coins au centre.","Pochez 8 minutes à l'eau salée, dressez sous le yaourt à l'ail et arrosez de beurre fondu au piment et à la menthe séchée."],
     en:["Knead the flour, eggs, water and salt for 15 minutes into a very firm dough, and rest it for an hour.","Chop the lamb with the onion and parsley, and season generously.","Roll the dough until you can see the grain of the table through it, then cut 2 cm squares.","Place a speck of filling the size of a rice grain on each, and pinch the four corners together at the centre.","Poach for 8 minutes in salted water, plate under garlic yogurt and pour over butter melted with chilli and dried mint."]} },

{ id:'tepsi-baytinijan', c:'as', lat:33.312, lon:44.361, base:6, prep:50, cook:60, diff:2, tags:['bake','beef','comfort'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'stew',food:['#6f4a5a','#c9402c','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Tepsi baytinijan',en:'Tepsi baytinijan'},
  p:{fr:'Bagdad, Irak',en:'Baghdad, Iraq'},
  d:{fr:"Un gratin d'aubergines frites, de boulettes de viande et de tomates, monté en couches dans un plateau. Tepsi désigne le plateau lui-même : à Bagdad, on l'envoyait au four du quartier faute de four à la maison.",
     en:"A gratin of fried aubergine, meatballs and tomato, layered in a tray. Tepsi means the tray itself: in Baghdad it was sent to the neighbourhood oven, since homes had none."},
  i:[['eggplant',1.2,'kg'],['ground_beef',600,'g'],['onion',3,'pc'],['ripe_tomato',600,'g'],['potato',500,'g'],['green_pepper',2,'pc'],['garlic',8,'clove'],['tomato_paste',3,'tbsp'],['baharat',1,'tbsp'],['parsley',4,'tbsp'],['frying_oil',600,'ml'],['long_grain_rice',400,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez les aubergines en rondelles épaisses, salez-les et laissez-les dégorger 30 minutes ; épongez-les soigneusement.","Faites-les frire jusqu'à ce qu'elles dorent, puis les pommes de terre et les poivrons dans la même huile.","Mêlez la viande hachée, l'oignon râpé, le persil et le baharat, et formez de petites boulettes plates, que vous saisissez.","Rangez en couches dans un plateau : aubergines, boulettes, pommes de terre, poivrons, tomates en rondelles.","Versez le concentré délayé dans un verre d'eau et enfournez 45 minutes à 190 °C. Servez avec du riz blanc."],
     en:["Cut the aubergines into thick rounds, salt them and let them drain for 30 minutes; pat them thoroughly dry.","Fry them until golden, then the potatoes and peppers in the same oil.","Mix the minced meat, grated onion, parsley and baharat, and shape small flat patties, which you sear.","Layer in a tray: aubergine, patties, potato, pepper, sliced tomato.","Pour over the tomato paste slaked in a glass of water and bake for 45 minutes at 190°C. Serve with white rice."]} },

{ id:'kibbeh-bil-sanieh', c:'as', lat:33.513, lon:36.276, base:8, prep:60, cook:45, diff:2, tags:['lamb','bake','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#8f5a3a','#c9924a','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Kibbé au plateau',en:'Kibbeh bil sanieh'},
  p:{fr:'Damas, Syrie',en:'Damascus, Syria'},
  d:{fr:"Deux couches de boulgour et d'agneau pilés, entre lesquelles on cache une farce de viande, d'oignon et de pignons. On y trace des losanges avant cuisson : c'est décoratif, mais surtout cela permet de couper les parts sans casser la croûte.",
     en:"Two layers of pounded bulgur and lamb, hiding a filling of meat, onion and pine nuts. Diamonds are scored before baking: decorative, but above all it lets you cut portions without breaking the crust."},
  i:[['lamb_leg',700,'g'],['bulgur',400,'g'],['onion',600,'g'],['ground_lamb',400,'g'],['pine_nuts',120,'g'],['allspice',2,'tsp'],['cinnamon',1,'tsp'],['butter',120,'g'],['olive_oil',80,'ml'],['pomegranate_molasses',2,'tbsp'],['plain_yogurt',400,'g'],['mint',1,'bunch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Rincez le boulgour fin et pressez-le ; il doit être humide, jamais détrempé.","Pilez le gigot paré avec un tiers de l'oignon et les épices, puis incorporez le boulgour en ajoutant de l'eau glacée par petites quantités jusqu'à obtenir une pâte lisse.","Faites la farce : oignon fondu, agneau haché, pignons grillés, mélasse de grenade, cannelle.","Étalez la moitié de la pâte sur 1 cm dans un plateau beurré, couvrez de farce, puis de la seconde moitié, en lissant à la main mouillée.","Tracez des losanges à la lame, arrosez de beurre fondu et enfournez 40 minutes à 200 °C. Servez avec un yaourt à la menthe."],
     en:["Rinse the fine bulgur and squeeze it; it should be damp, never sodden.","Pound the trimmed leg with a third of the onion and the spices, then work in the bulgur, adding iced water little by little until the paste is smooth.","Make the filling: softened onion, minced lamb, toasted pine nuts, pomegranate molasses, cinnamon.","Spread half the paste 1 cm thick in a buttered tray, cover with the filling, then the second half, smoothing with a wet hand.","Score diamonds with a blade, pour over melted butter and bake for 40 minutes at 200°C. Serve with minted yogurt."]} },

{ id:'maftoul', c:'as', lat:31.905, lon:35.206, base:6, prep:90, cook:75, diff:3, tags:['poultry','comfort','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'rice',food:['#c9924a','#e0b45a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Maftoul',en:'Maftoul'},
  p:{fr:'Ramallah, Palestine',en:'Ramallah, Palestine'},
  d:{fr:"Un couscous palestinien roulé à la main en perles beaucoup plus grosses qu'au Maghreb, servi avec poulet et pois chiches. Rouler le maftoul est un savoir de village : on le fait à plusieurs, sur un grand plateau.",
     en:"A Palestinian couscous hand-rolled into pearls far larger than in the Maghreb, served with chicken and chickpeas. Rolling maftoul is village knowledge: it is done by several people, on a large tray."},
  i:[['bulgur',300,'g'],['flour',300,'g'],['chicken',1.5,'kg'],['chickpeas',250,'g'],['onion',4,'pc'],['allspice',2,'tsp'],['cinnamon',1,'tsp'],['turmeric',1,'tsp'],['cardamom',6,'pc'],['bay_leaf',2,'pc'],['olive_oil',120,'ml'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Humectez le boulgour fin d'eau salée et roulez-le sur un plateau en le saupoudrant de farine, par mouvements circulaires.","Continuez jusqu'à obtenir des perles de la taille d'un grain de poivre, puis tamisez pour écarter la farine libre.","Pochez le poulet 50 minutes avec les épices entières et l'oignon ; gardez le bouillon.","Cuisez le maftoul 25 minutes à la vapeur au-dessus du bouillon, en l'égrenant deux fois à la fourchette.","Faites fondre les oignons émincés à l'huile d'olive, mêlez-les au maftoul avec les pois chiches, et dressez le poulet dessus."],
     en:["Moisten the fine bulgur with salted water and roll it on a tray, dusting with flour, in circular movements.","Continue until the pearls are the size of a peppercorn, then sift to remove loose flour.","Poach the chicken for 50 minutes with the whole spices and onion; keep the broth.","Steam the maftoul for 25 minutes above the broth, fluffing it twice with a fork.","Soften the sliced onions in olive oil, fold them into the maftoul with the chickpeas, and set the chicken on top."]} },

{ id:'galayet-bandora', c:'as', lat:31.955, lon:35.945, base:4, prep:15, cook:30, diff:1, tags:['veg','fast','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f4ecd8',style:'stew',food:['#c9402c','#8f3b2a','#e0913a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Galayet bandora',en:'Galayet bandora'},
  p:{fr:'Amman, Jordanie',en:'Amman, Jordan'},
  d:{fr:"Des tomates saisies à l'huile d'olive avec de l'ail et du piment vert, réduites jusqu'à confire. C'est le plat des récoltes de septembre : quand la tomate abonde, on la fait griller plutôt que de la mijoter.",
     en:"Tomatoes seared in olive oil with garlic and green chilli, reduced until jammy. It is the September harvest dish: when tomatoes are abundant, they are scorched rather than stewed."},
  i:[['ripe_tomato',1.2,'kg'],['garlic',10,'clove'],['green_chili',4,'pc'],['olive_oil',150,'ml'],['onion',1,'pc'],['aleppo_pepper',1,'tsp'],['pita_bread',6,'pc'],['mint',1,'bunch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Choisissez des tomates très mûres et coupez-les en gros quartiers, sans les peler ni les épépiner.","Faites chauffer l'huile d'olive jusqu'à ce qu'elle frémisse, et jetez-y l'ail entier écrasé et les piments verts fendus.","Ajoutez les tomates d'un coup et laissez-les saisir sans y toucher 5 minutes : elles doivent noircir par endroits.","Écrasez-les grossièrement à la cuillère et laissez réduire 20 minutes à découvert.","Poivrez, ajoutez le piment d'Alep et la menthe hors du feu. On mange à la poêle, en trempant le pain."],
     en:["Choose very ripe tomatoes and cut them into large wedges, without peeling or seeding them.","Heat the olive oil until it shimmers, and drop in the crushed whole garlic and split green chillies.","Add the tomatoes all at once and let them sear untouched for 5 minutes: they should blacken in places.","Crush them roughly with a spoon and reduce uncovered for 20 minutes.","Season, add the Aleppo pepper and mint off the heat. It is eaten from the pan, dipping bread."]} },

{ id:'sayadieh', c:'as', lat:34.436, lon:35.849, base:6, prep:45, cook:70, diff:2, tags:['sea','rice','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'rice',food:['#8f6a4a','#c9a878','#f0e8d0','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Sayadieh',en:'Sayadieh'},
  p:{fr:'Tripoli, Liban',en:'Tripoli, Lebanon'},
  d:{fr:"Un riz brun cuit dans un bouillon de poisson et d'oignons caramélisés, surmonté de darnes frites et d'une sauce au tahini. La couleur ne vient d'aucune épice : elle vient uniquement des oignons poussés jusqu'au brun sombre.",
     en:"Brown rice cooked in a broth of fish and caramelised onions, topped with fried steaks and a tahini sauce. The colour comes from no spice: only from onions taken to a deep brown."},
  i:[['sea_bream',1.5,'kg'],['long_grain_rice',500,'g'],['onion',800,'g'],['cumin',1,'tbsp'],['cinnamon',1,'tsp'],['bay_leaf',3,'pc'],['tahini',150,'g'],['lemon',3,'pc'],['garlic',5,'clove'],['pine_nuts',80,'g'],['almonds',80,'g'],['olive_oil',200,'ml'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Salez les darnes de poisson et laissez-les reposer 30 minutes, puis épongez-les et faites-les frire ; réservez.","Faites frire les oignons émincés dans la même huile 30 minutes, jusqu'au brun foncé : c'est cette étape, et rien d'autre, qui donne la couleur.","Prélevez-en un tiers pour le service, et mixez le reste avec un litre d'eau chaude ; filtrez ce bouillon brun.","Faites-y cuire le riz avec le cumin, la cannelle et le laurier, 18 minutes à couvert.","Fouettez le tahini avec le citron, l'ail et un peu d'eau jusqu'à ce qu'il blanchisse. Dressez riz, poisson, oignons frits, amandes et pignons, sauce à part."],
     en:["Salt the fish steaks and let them stand for 30 minutes, then pat dry and fry them; set aside.","Fry the sliced onions in the same oil for 30 minutes, to a deep brown: this step, and nothing else, gives the colour.","Take out a third for serving, and blend the rest with a litre of hot water; strain this brown broth.","Cook the rice in it with the cumin, cinnamon and bay, 18 minutes covered.","Whisk the tahini with lemon, garlic and a little water until it whitens. Plate rice, fish, fried onions, almonds and pine nuts, sauce alongside."]} },

{ id:'zurbian', c:'as', lat:12.785, lon:45.019, base:8, prep:50, cook:105, diff:2, tags:['rice','lamb','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'rice',food:['#e0b45a','#c9402c','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Zurbian',en:'Zurbian'},
  p:{fr:'Aden, Yémen',en:'Aden, Yemen'},
  d:{fr:"Un riz d'agneau au yaourt, au safran et aux pommes de terre, cuit en couches et parfumé au bois d'agar. On le fume en fin de cuisson : un charbon posé dans une coupelle au cœur du riz, sous couvercle.",
     en:"A lamb rice with yogurt, saffron and potato, cooked in layers and scented with agarwood. It is smoked at the end: a coal set in a small dish in the heart of the rice, under the lid."},
  i:[['lamb_shoulder',1.2,'kg'],['basmati_rice',700,'g'],['plain_yogurt',400,'g'],['potato',500,'g'],['onion',4,'pc'],['garlic',10,'clove'],['ginger',50,'g'],['saffron',1,'pinch'],['cardamom',8,'pc'],['cinnamon',2,'pc'],['cloves',6,'pc'],['hawaij',2,'tbsp'],['ghee',150,'g'],['raisins',80,'g'],['almonds',80,'g'],['salt',null,'']],
  s:{fr:["Faites mariner l'agneau 4 heures dans le yaourt, l'ail, le gingembre et le hawaij.","Faites frire les oignons émincés jusqu'au brun foncé et réservez-en la moitié.","Faites cuire l'agneau et sa marinade 1 heure avec les épices entières, puis ajoutez les pommes de terre.","Précuisez le riz 6 minutes à grande eau salée et égouttez-le à moitié cuit.","Montez en couches viande, riz, oignons frits, safran et ghee ; couvrez 30 minutes à feu doux, puis fumez au charbon 5 minutes."],
     en:["Marinate the lamb for 4 hours in the yogurt, garlic, ginger and hawaij.","Fry the sliced onions to a deep brown and set half aside.","Cook the lamb and its marinade for 1 hour with the whole spices, then add the potatoes.","Par-boil the rice for 6 minutes in plenty of salted water and drain it half cooked.","Layer meat, rice, fried onion, saffron and ghee; cover for 30 minutes over low heat, then smoke with a coal for 5 minutes."]} },

{ id:'qoozi-bahreini', c:'as', lat:26.204, lon:50.581, base:10, prep:60, cook:240, diff:2, tags:['lamb','festive','slow'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'rice',food:['#e0b45a','#8f5a3a','#c98a2c','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Qoozi',en:'Qoozi'},
  p:{fr:'Manama, Bahreïn',en:'Manama, Bahrain'},
  d:{fr:"Un agneau entier posé sur une montagne de riz aux fruits secs, cuit quatre heures à basse température. On le sert au centre de la table pour les mariages, et l'on démonte la bête à la main, sans couteau.",
     en:"A whole lamb set on a mountain of rice with dried fruit, cooked four hours at low temperature. It is served at the centre of the table for weddings, and taken apart by hand, without a knife."},
  i:[['lamb_leg',3,'kg'],['basmati_rice',1,'kg'],['onion',4,'pc'],['baharat',3,'tbsp'],['dried_lime',3,'pc'],['cardamom',10,'pc'],['cinnamon',3,'pc'],['saffron',1,'pinch'],['raisins',150,'g'],['almonds',120,'g'],['pine_nuts',80,'g'],['carrot',3,'pc'],['ghee',250,'g'],['rose_water',1,'tbsp'],['salt',null,'']],
  s:{fr:["Frottez l'agneau de baharat, de sel et de ghee fondu, et laissez-le 6 heures au frais.","Enfermez-le dans un plat couvert avec un fond d'eau et cuisez 3 h 30 à 150 °C : la vapeur fait tout le travail.","Filtrez le jus rendu et utilisez-le pour cuire le riz trempé, avec les loomi percés et les épices entières.","Faites frire séparément amandes, pignons et raisins dans le ghee, et taillez les carottes en fine julienne confite.","Découvrez l'agneau et passez-le 25 minutes à 220 °C pour dorer. Dressez-le sur le riz, couvert de fruits secs et de safran à l'eau de rose."],
     en:["Rub the lamb with baharat, salt and melted ghee, and leave it 6 hours in the cold.","Seal it in a covered dish with a little water and cook for 3½ hours at 150°C: the steam does all the work.","Strain the released juices and use them to cook the soaked rice, with the pierced dried limes and whole spices.","Fry the almonds, pine nuts and raisins separately in ghee, and candy the carrots cut into fine julienne.","Uncover the lamb and give it 25 minutes at 220°C to colour. Set it on the rice, covered with the nuts and saffron in rose water."]} },

{ id:'mashuai', c:'as', lat:23.614, lon:58.593, base:6, prep:35, cook:60, diff:2, tags:['sea','grill','festive'],
  art:{v:'board',bg:'#26384a',plate:'#f2ead6',style:'fish',food:['#e0b45a','#c9924a','#f0e8d0','#c9402c'],garnish:'#7fae6a'},
  n:{fr:'Mashuai',en:'Mashuai'},
  p:{fr:'Mascate, Oman',en:'Muscat, Oman'},
  d:{fr:"Un thazard entier grillé sur la braise, servi sur un riz au citron noir. Le poisson n'est frotté que de sel et de curcuma : à Mascate, on considère qu'un bon poisson n'a besoin de rien d'autre.",
     en:"A whole kingfish grilled over coals, served on black-lime rice. The fish is rubbed only with salt and turmeric: in Muscat a good fish is held to need nothing else."},
  i:[['kingfish',2,'kg'],['turmeric',2,'tbsp'],['basmati_rice',600,'g'],['dried_lime',3,'pc'],['onion',2,'pc'],['garlic',8,'clove'],['lemon',3,'pc'],['ghee',100,'g'],['cardamom',6,'pc'],['cilantro',1,'bunch'],['coarse_salt',3,'tbsp'],['pepper',null,'']],
  s:{fr:["Videz et écaillez le poisson, entaillez-le trois fois de chaque côté jusqu'à l'arête.","Frottez-le de curcuma, de gros sel et d'ail pilé, en insistant dans les entailles, et laissez-le 1 heure.","Grillez-le sur des braises modérées 20 minutes par face, en l'arrosant de ghee citronné.","Cuisez le riz avec les loomi percés, la cardamome et l'oignon frit, dans une eau à peine salée.","Servez le poisson entier sur le riz, avec du citron et de la coriandre. On l'ouvre à table, à la main."],
     en:["Gut and scale the fish, and score it three times on each side down to the bone.","Rub it with turmeric, coarse salt and pounded garlic, working into the cuts, and leave it 1 hour.","Grill it over moderate coals for 20 minutes a side, basting with lemon ghee.","Cook the rice with the pierced dried limes, cardamom and fried onion, in barely salted water.","Serve the whole fish on the rice, with lemon and coriander. It is opened at the table, by hand."]} },

{ id:'balaleet', c:'as', lat:25.276, lon:55.296, base:4, prep:20, cook:25, diff:1, tags:['breakfast','sweet','fast'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'noodle',food:['#e8c46a','#f4f0e6','#e0b45a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Balaleet',en:'Balaleet'},
  p:{fr:'Dubaï, Émirats arabes unis',en:'Dubai, United Arab Emirates'},
  d:{fr:"Des vermicelles sucrés au safran et à la cardamome, couverts d'une omelette fine et salée. Le sucré-salé simultané déroute les visiteurs ; aux Émirats, c'est le petit-déjeuner de l'Aïd depuis toujours.",
     en:"Sweet vermicelli with saffron and cardamom, covered with a thin savoury omelette. The simultaneous sweet and salty disconcerts visitors; in the Emirates it has always been the Eid breakfast."},
  i:[['vermicelli',400,'g'],['sugar',120,'g'],['saffron',1,'pinch'],['cardamom',1,'tsp'],['rose_water',1,'tbsp'],['ghee',100,'g'],['egg',6,'pc'],['whole_milk',60,'ml'],['pistachios',50,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Cassez les vermicelles à la main en tronçons de 4 cm et faites-les dorer dans le ghee, en remuant sans arrêt.","Ils doivent devenir noisette et non brun : dix secondes de trop et ils deviennent amers.","Versez de l'eau bouillante à hauteur, salez à peine, et laissez cuire 6 minutes.","Ajoutez le sucre, le safran infusé, la cardamome et l'eau de rose, et laissez évaporer complètement à découvert.","Faites une omelette très fine et à peine prise, salée et poivrée, et posez-la entière sur les vermicelles. Pistaches par-dessus."],
     en:["Break the vermicelli by hand into 4 cm lengths and colour them in the ghee, stirring constantly.","They should turn hazelnut, not brown: ten seconds too long and they turn bitter.","Pour in boiling water to cover, barely salt it, and cook for 6 minutes.","Add the sugar, infused saffron, cardamom and rose water, and let it evaporate completely, uncovered.","Make a very thin, barely set omelette, seasoned, and lay it whole over the vermicelli. Pistachios on top."]} },

{ id:'khoresh-fesenjan', c:'as', lat:36.566, lon:53.060, base:6, prep:30, cook:180, diff:2, tags:['poultry','slow','festive'],
  art:{v:'pot',bg:'#2b2419',plate:'#f4ecd8',style:'stew',food:['#3a2a1a','#6f4a2a','#8f1a3a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Khoresh fesenjan',en:'Khoresh fesenjan'},
  p:{fr:'Sari, Mazandaran, Iran',en:'Sari, Mazandaran, Iran'},
  d:{fr:"Un ragoût brun sombre de noix moulues et de mélasse de grenade, aigre-doux et très ancien. On en trouve la trace sur des tablettes assyriennes ; à Sari, on le sert au canard plutôt qu'au poulet.",
     en:"A dark brown stew of ground walnuts and pomegranate molasses, sweet-sour and very old. It appears on Assyrian tablets; in Sari it is served with duck rather than chicken."},
  i:[['chicken',1.5,'kg'],['walnuts',500,'g'],['pomegranate_molasses',250,'ml'],['onion',3,'pc'],['sugar',3,'tbsp'],['turmeric',1,'tsp'],['cinnamon',1,'tsp'],['saffron',1,'pinch'],['pomegranate',1,'pc'],['basmati_rice',600,'g'],['butter',80,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Moulez les noix très finement, presque en pâte, puis faites-les griller à sec 10 minutes à feu doux en remuant sans arrêt.","Faites blondir les oignons, ajoutez le curcuma, puis le poulet, et laissez colorer.","Ajoutez les noix et un litre d'eau chaude, et laissez mijoter 1 h 30 à découvert, en remuant souvent.","L'huile des noix doit remonter et le ragoût foncer jusqu'au brun presque noir : c'est le seul indicateur de cuisson.","Ajoutez la mélasse de grenade, le sucre et le safran, et laissez encore 30 minutes. Servez sur du riz au safran avec des grains de grenade."],
     en:["Grind the walnuts very finely, almost to a paste, then dry-toast them for 10 minutes over low heat, stirring constantly.","Fry the onions golden, add the turmeric, then the chicken, and let it colour.","Add the walnuts and a litre of hot water, and simmer uncovered for 1½ hours, stirring often.","The walnut oil must rise and the stew darken to almost black-brown: it is the only test of doneness.","Add the pomegranate molasses, sugar and saffron, and give it another 30 minutes. Serve over saffron rice with pomegranate seeds."]} },

{ id:'dolma-azerbaidjan', c:'as', lat:40.409, lon:49.867, base:6, prep:75, cook:60, diff:2, tags:['lamb','veg','festive'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'stew',food:['#4f6f3a','#7fae5a','#8f5a3a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Dolma des trois sœurs',en:'Three sisters dolma'},
  p:{fr:'Bakou, Azerbaïdjan',en:'Baku, Azerbaijan'},
  d:{fr:"Trois légumes farcis servis ensemble — tomate, poivron et aubergine —, appelés les trois sœurs. La dolma azerbaïdjanaise est inscrite à l'UNESCO ; la menthe et le fenouil dans la farce la distinguent de ses voisines.",
     en:"Three stuffed vegetables served together — tomato, pepper and aubergine — called the three sisters. Azerbaijani dolma is UNESCO-listed; the mint and fennel in the filling set it apart from its neighbours."},
  i:[['ripe_tomato',6,'pc'],['green_pepper',6,'pc'],['eggplant',6,'pc'],['ground_lamb',600,'g'],['long_grain_rice',150,'g'],['onion',2,'pc'],['mint',1,'bunch'],['cilantro',1,'bunch'],['dill',1,'bunch'],['fennel',1,'tbsp'],['butter',100,'g'],['plain_yogurt',400,'g'],['garlic',5,'clove'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Décalottez les trois légumes et videz-les délicatement, en gardant les chapeaux : les parois doivent rester assez épaisses pour tenir.","Salez l'intérieur des aubergines et laissez-les dégorger 20 minutes, puis rincez-les.","Mêlez l'agneau haché, le riz cru, l'oignon très finement haché, les herbes ciselées et le fenouil moulu.","Farcissez sans tasser — le riz gonfle — et recoiffez chaque légume de son chapeau.","Rangez-les serrés dans une cocotte, ajoutez un verre d'eau et le beurre, couvrez et laissez cuire 50 minutes à feu doux. Servez avec un yaourt à l'ail."],
     en:["Cut the tops off the three vegetables and hollow them carefully, keeping the lids: the walls must stay thick enough to hold.","Salt the inside of the aubergines and let them drain for 20 minutes, then rinse them.","Mix the minced lamb, raw rice, very finely chopped onion, chopped herbs and ground fennel.","Fill without packing — the rice swells — and replace each vegetable's lid.","Pack them tightly in a pot, add a glass of water and the butter, cover and cook for 50 minutes over low heat. Serve with garlic yogurt."]} },

{ id:'harissa-armenienne', c:'as', lat:40.183, lon:44.515, base:8, prep:20, cook:300, diff:1, tags:['poultry','slow','comfort'],
  art:{v:'bowl',bg:'#33301f',plate:'#f4f0e6',style:'soup',food:['#f4f0e6','#f0e8d0','#e8dcc0','#e0b45a'],garnish:'#c9754a'},
  n:{fr:'Harissa arménienne',en:'Armenian harissa'},
  p:{fr:'Erevan, Arménie',en:'Yerevan, Armenia'},
  d:{fr:"Une bouillie de blé mondé et de poulet battue jusqu'à devenir soyeuse, sans sel avant la fin. La tradition la lie au siège de Musa Dagh : les villageois auraient mis en commun ce qui restait de blé et de volaille.",
     en:"A porridge of hulled wheat and chicken beaten until silky, unsalted until the very end. Tradition links it to the siege of Musa Dagh: villagers are said to have pooled the last of their wheat and poultry."},
  i:[['hulled_wheat',600,'g'],['chicken',1.8,'kg'],['butter',250,'g'],['cumin',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper le blé mondé une nuit dans l'eau froide.","Pochez le poulet 1 heure dans quatre litres d'eau, désossez-le et remettez la chair dans le bouillon.","Ajoutez le blé égoutté et laissez cuire 4 heures à feu très doux, en remuant toutes les demi-heures pour que rien n'attache.","Battez au fouet ou au pilon la dernière heure, jusqu'à ce que le blé et la viande ne fassent plus qu'une crème.","Ne salez qu'à la toute fin — salée trop tôt, la harissa ne se lie jamais. Servez sous une nappe de beurre noisette au cumin."],
     en:["Soak the hulled wheat overnight in cold water.","Poach the chicken for 1 hour in four litres of water, bone it and return the meat to the broth.","Add the drained wheat and cook for 4 hours over very low heat, stirring every half hour so nothing catches.","Beat with a whisk or pestle for the last hour, until wheat and meat become a single cream.","Salt only at the very end — salted too early, harissa never binds. Serve under a pool of cumin-browned butter."]} },

{ id:'khinkali', c:'as', lat:42.470, lon:44.660, base:6, prep:90, cook:15, diff:3, tags:['lamb','comfort','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4f0e6',style:'pastry',food:['#f4f0e6','#f0e8d0','#e8dcc0','#c9a878'],garnish:'#7fae6a'},
  n:{fr:'Khinkali',en:'Khinkali'},
  p:{fr:'Pasanauri, Khevsourétie, Géorgie',en:'Pasanauri, Khevsureti, Georgia'},
  d:{fr:"De gros raviolis à la viande dont on boit d'abord le bouillon, en mordant sur le côté. On tient le khinkali par sa queue de pâte, qu'on ne mange jamais : les convives comptent les queues laissées dans l'assiette.",
     en:"Large meat dumplings whose broth is drunk first, biting into the side. You hold the khinkali by its dough tail, which is never eaten: guests count the tails left on the plate."},
  i:[['flour',600,'g'],['water',280,'ml'],['ground_lamb',400,'g'],['ground_beef',300,'g'],['onion',300,'g'],['garlic',6,'clove'],['cilantro',1,'bunch'],['blue_fenugreek',2,'tsp'],['caraway',1,'tsp'],['chili_flakes',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez farine, eau et sel 15 minutes en une pâte très ferme, et laissez-la reposer une heure sous un linge.","Mêlez les viandes hachées, l'oignon râpé, l'ail, la coriandre et les épices avec 200 ml d'eau glacée : la farce doit être franchement liquide, c'est elle qui deviendra le bouillon.","Étalez des disques de 12 cm, plus épais au centre qu'aux bords.","Déposez une grosse cuillerée de farce et plissez le bord en tournant, en comptant au moins dix-neuf plis, puis pincez la queue.","Pochez 12 minutes à l'eau frémissante salée. Poivrez généreusement, mordez le flanc, buvez le jus, puis mangez — en laissant la queue."],
     en:["Knead the flour, water and salt for 15 minutes into a very firm dough, and rest it for an hour under a cloth.","Mix the minced meats, grated onion, garlic, coriander and spices with 200 ml of iced water: the filling must be frankly liquid, as it becomes the broth.","Roll 12 cm discs, thicker at the centre than at the edges.","Place a large spoonful of filling and pleat the edge round, counting at least nineteen folds, then pinch the tail.","Poach for 12 minutes in barely simmering salted water. Pepper generously, bite the side, drink the juice, then eat — leaving the tail."]} },

{ id:'chakapuli', c:'as', lat:41.649, lon:45.694, base:6, prep:25, cook:60, diff:1, tags:['lamb','fresh','comfort'],
  art:{v:'pot',bg:'#28331f',plate:'#f4ecd8',style:'stew',food:['#7fae5a','#4f8f4a','#f0e8d0','#e8dcb8'],garnish:'#6fbf8f'},
  n:{fr:'Chakapuli',en:'Chakapuli'},
  p:{fr:'Telavi, Kakhétie, Géorgie',en:'Telavi, Kakheti, Georgia'},
  d:{fr:"De l'agneau de lait mijoté dans du vin blanc avec des prunes vertes acides et une montagne d'estragon. C'est un plat de printemps strictement saisonnier : sans tkemali vertes ni estragon frais, il ne se fait pas.",
     en:"Milk-fed lamb stewed in white wine with sour green plums and a mountain of tarragon. A strictly seasonal spring dish: without green tkemali and fresh tarragon, it is not made."},
  i:[['lamb_shoulder',1.2,'kg'],['green_plums',500,'g'],['tarragon',4,'bunch'],['spring_onion',10,'pc'],['white_wine',400,'ml'],['garlic',10,'clove'],['cilantro',2,'bunch'],['parsley',1,'bunch'],['chili_pepper',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez l'agneau en gros morceaux avec l'os et rangez-le au fond d'une cocotte, sans matière grasse ni coloration préalable.","Couvrez d'une couche épaisse d'oignons verts émincés et des prunes vertes entières.","Versez le vin blanc — il ne doit pas recouvrir la viande — couvrez et laissez cuire 40 minutes à feu doux.","Ajoutez alors l'estragon effeuillé en très grande quantité, la coriandre, le persil, l'ail et le piment.","Poursuivez 20 minutes à couvert : les herbes doivent tomber sans noircir. On sert dans la cocotte, avec du pain."],
     en:["Cut the lamb into large pieces on the bone and lay it in a pot, with no fat and no prior browning.","Cover with a thick layer of sliced spring onions and the whole green plums.","Pour in the white wine — it should not cover the meat — put on the lid and cook for 40 minutes over low heat.","Only then add the picked tarragon in very large quantity, with coriander, parsley, garlic and chilli.","Continue for 20 minutes covered: the herbs should wilt without blackening. Serve in the pot, with bread."]} },

{ id:'beshbarmak-kazakh', c:'as', lat:43.238, lon:76.889, base:8, prep:60, cook:180, diff:2, tags:['beef','festive','noodles'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'noodle',food:['#f4f0e6','#8f5a3a','#e8dcc0','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Besbarmak d’Almaty',en:'Almaty besbarmaq'},
  p:{fr:'Almaty, Kazakhstan',en:'Almaty, Kazakhstan'},
  d:{fr:"De la viande de cheval et d'agneau bouillie, servie sur de larges carrés de pâte et arrosée d'oignons au bouillon. Le nom veut dire « cinq doigts » : il se mange à la main, et l'aîné distribue les morceaux selon le rang.",
     en:"Boiled horse and lamb served on wide squares of pasta and moistened with onions in broth. The name means 'five fingers': it is eaten by hand, and the eldest distributes the pieces by rank."},
  i:[['horse_meat',1.2,'kg'],['lamb_shoulder',800,'g'],['kazy_sausage',400,'g'],['flour',600,'g'],['egg',2,'pc'],['onion',600,'g'],['bay_leaf',3,'pc'],['black_peppercorns',1,'tbsp'],['parsley',3,'tbsp'],['salt',null,'']],
  s:{fr:["Faites cuire les viandes 2 h 30 à frémissement dans une grande marmite, en écumant sans relâche.","Pétrissez farine, œufs, un peu de bouillon et sel en une pâte ferme ; laissez reposer 40 minutes.","Étalez-la très finement et découpez des losanges de 8 cm.","Pochez-les 5 minutes dans le bouillon dégraissé — jamais à l'eau claire, ils perdraient tout leur goût.","Faites tomber les oignons en anneaux dans une louche de bouillon brûlant. Dressez pâte, viande tranchée et oignons, et servez le bouillon à part, en bol."],
     en:["Simmer the meats for 2½ hours in a large pot, skimming relentlessly.","Knead the flour, eggs, a little broth and salt into a firm dough; rest it for 40 minutes.","Roll it very thin and cut 8 cm diamonds.","Poach them for 5 minutes in the skimmed broth — never in plain water, they would lose all their flavour.","Wilt the onion rings in a ladle of scalding broth. Plate the pasta, sliced meat and onions, and serve the broth separately, in bowls."]} },

{ id:'oshi-palav-tadjik', c:'as', lat:38.560, lon:68.787, base:8, prep:45, cook:120, diff:2, tags:['rice','lamb','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'rice',food:['#e0b45a','#c98a2c','#8f5a3a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Oshi palav',en:'Oshi palav'},
  p:{fr:'Douchanbé, Tadjikistan',en:'Dushanbe, Tajikistan'},
  d:{fr:"Le palov tadjik, aux carottes jaunes et rouges mêlées, cuit dans un kazan et servi sur un plat unique. Inscrit à l'UNESCO en 2016 : c'est le plat qui accompagne toutes les naissances et tous les mariages du pays.",
     en:"Tajik palov, with yellow and red carrots mixed, cooked in a kazan and served on a single platter. UNESCO-listed in 2016: it accompanies every birth and every wedding in the country."},
  i:[['lamb_shoulder',1,'kg'],['lamb_fat',150,'g'],['long_grain_rice',800,'g'],['yellow_carrot',600,'g'],['carrot',600,'g'],['onion',400,'g'],['garlic',3,'pc'],['cumin',2,'tbsp'],['barberries',2,'tbsp'],['chickpeas',150,'g'],['quince',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Rincez le riz jusqu'à l'eau claire et faites-le tremper dans l'eau tiède salée.","Faites fondre le gras de mouton dans le kazan, retirez les grattons, et saisissez la viande à feu vif.","Ajoutez l'oignon, puis les carottes jaunes et rouges en bâtonnets épais, sans jamais les râper.","Mouillez à hauteur, ajoutez pois chiches, coing, têtes d'ail et cumin, et laissez le zirvak mijoter 40 minutes.","Étalez le riz par-dessus sans mélanger, ajoutez de l'eau bouillante à deux doigts, laissez évaporer puis couvrez 25 minutes. Renversez sur le plat au service."],
     en:["Rinse the rice until the water runs clear and soak it in warm salted water.","Render the mutton fat in the kazan, remove the scratchings, and sear the meat over high heat.","Add the onion, then the yellow and red carrots in thick batons, never grated.","Cover with water, add chickpeas, quince, garlic heads and cumin, and let the zirvak simmer for 40 minutes.","Spread the rice on top without stirring, add boiling water to two fingers, let it evaporate then cover for 25 minutes. Invert onto the platter to serve."]} },

{ id:'dograma', c:'as', lat:37.960, lon:58.326, base:6, prep:40, cook:150, diff:1, tags:['lamb','soup','festive'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ecd8',style:'soup',food:['#e8dcb8','#8f5a3a','#f0e8d0','#c9a878'],garnish:'#7fae6a'},
  n:{fr:'Dograma',en:'Dograma'},
  p:{fr:'Achgabat, Turkménistan',en:'Ashgabat, Turkmenistan'},
  d:{fr:"Du pain plat, de la viande et de l'oignon émiettés à la main dans un bouillon d'agneau brûlant. Tout doit être déchiré aux doigts, jamais coupé : le couteau est proscrit, et l'on dit que la lame gâte le goût.",
     en:"Flatbread, meat and onion crumbled by hand into a scalding lamb broth. Everything must be torn by finger, never cut: the knife is banned, and the blade is said to spoil the taste."},
  i:[['lamb_shoulder',1.2,'kg'],['lamb_fat',150,'g'],['churek_bread',4,'pc'],['onion',500,'g'],['ripe_tomato',300,'g'],['black_peppercorns',1,'tbsp'],['bay_leaf',2,'pc'],['salt',null,'']],
  s:{fr:["Faites cuire l'agneau et le gras 2 heures dans trois litres d'eau avec le laurier, en écumant.","Retirez la viande, laissez-la tiédir, puis effilochez-la entièrement à la main.","Émiettez le pain churek entre les doigts, en morceaux irréguliers de la taille d'un ongle.","Émincez l'oignon très finement, salez-le et froissez-le à la main pour l'attendrir.","Mêlez pain, viande, oignon et tomate dans un grand bol, versez le bouillon brûlant dessus et servez aussitôt, avant que le pain ne se défasse."],
     en:["Cook the lamb and fat for 2 hours in three litres of water with the bay, skimming.","Lift out the meat, let it cool, then shred it entirely by hand.","Crumble the churek bread between your fingers, into irregular pieces the size of a fingernail.","Slice the onion very finely, salt it and crush it by hand to soften it.","Combine bread, meat, onion and tomato in a large bowl, pour the scalding broth over and serve at once, before the bread collapses."]} },

{ id:'ashak', c:'as', lat:34.531, lon:69.166, base:6, prep:90, cook:30, diff:3, tags:['veg','comfort','festive'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'pastry',food:['#f0e8d0','#4f8f4a','#c9402c','#f4f0e6'],garnish:'#6fbf8f'},
  n:{fr:'Ashak',en:'Ashak'},
  p:{fr:'Kaboul, Afghanistan',en:'Kabul, Afghanistan'},
  d:{fr:"Des raviolis à la ciboule sauvage, nappés d'un yaourt à l'ail et d'une sauce de viande aux pois cassés. La ciboule gandana ne pousse qu'en Afghanistan ; les exilés la remplacent par du poireau, en s'en excusant toujours.",
     en:"Dumplings of wild garlic chives under garlic yogurt and a meat sauce with split peas. The gandana chive grows only in Afghanistan; exiles substitute leek, and always apologise for it."},
  i:[['flour',500,'g'],['water',220,'ml'],['leek',600,'g'],['spring_onion',10,'pc'],['ground_beef',400,'g'],['yellow_peas',150,'g'],['onion',2,'pc'],['tomato_paste',2,'tbsp'],['plain_yogurt',600,'g'],['garlic',8,'clove'],['dried_mint',2,'tbsp'],['chili_flakes',1,'tsp'],['coriander_seeds',1,'tsp'],['peanut_oil',100,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez farine, eau et sel 12 minutes en une pâte ferme et laissez-la reposer une heure.","Émincez très finement poireau et oignons verts, salez-les et laissez-les dégorger 20 minutes, puis pressez-les à fond : toute l'eau doit sortir.","Étalez la pâte très mince, découpez des disques de 8 cm, garnissez et refermez en demi-lune en plissant le bord.","Faites une sauce avec l'oignon, le bœuf haché, les pois cassés trempés, le concentré et la coriandre moulue, 40 minutes.","Pochez les ashak 6 minutes, dressez-les sur le yaourt à l'ail, nappez de sauce et saupoudrez de menthe séchée."],
     en:["Knead the flour, water and salt for 12 minutes into a firm dough and rest it for an hour.","Slice the leek and spring onions very finely, salt them and let them drain for 20 minutes, then squeeze them hard: every drop must go.","Roll the dough very thin, cut 8 cm discs, fill them and seal into half-moons, pleating the edge.","Make a sauce with the onion, minced beef, soaked split peas, tomato paste and ground coriander, 40 minutes.","Poach the ashak for 6 minutes, set them on the garlic yogurt, spoon over the sauce and dust with dried mint."]} },

{ id:'sajji-baloutche', c:'as', lat:30.183, lon:66.975, base:6, prep:40, cook:120, diff:2, tags:['poultry','grill','festive'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#c9754a','#8f5a2b','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Sajji',en:'Sajji'},
  p:{fr:'Quetta, Baloutchistan, Pakistan',en:'Quetta, Balochistan, Pakistan'},
  d:{fr:"Un poulet entier planté sur une broche de bois autour d'un feu ouvert, salé seulement, sans épices. Les Baloutches jugent la cuisson au son : la peau doit craquer quand on la frappe du dos d'un couteau.",
     en:"A whole chicken staked on a wooden skewer around an open fire, salted only, without spices. The Baloch judge doneness by sound: the skin must crack when struck with the back of a knife."},
  i:[['chicken',1.8,'kg'],['coarse_salt',3,'tbsp'],['papaya_paste',3,'tbsp'],['lemon',3,'pc'],['long_grain_rice',400,'g'],['chaat_masala',1,'tbsp'],['onion',2,'pc'],['ripe_tomato',300,'g'],['green_chili',3,'pc'],['flatbread',6,'pc'],['pepper',null,'']],
  s:{fr:["Entaillez le poulet profondément et frottez-le de gros sel, de citron et de pâte de papaye verte, qui attendrit les fibres.","Laissez-le 4 heures : plus longtemps, la papaye défait la chair.","Farcissez-le d'un riz à demi cuit, recousez l'ouverture et embrochez-le sur un bâton de bois vert.","Plantez la broche en biais à quarante centimètres d'un feu de bois et tournez-la toutes les dix minutes, pendant 1 h 30.","Frappez la peau : si elle sonne creux et se fend, c'est prêt. Saupoudrez de chaat masala et servez avec du pain et de l'oignon cru."],
     en:["Score the chicken deeply and rub it with coarse salt, lemon and green papaya paste, which tenderises the fibres.","Leave it 4 hours: any longer and the papaya breaks the flesh down.","Stuff it with half-cooked rice, sew the opening shut and stake it on a green wooden skewer.","Plant the skewer at an angle forty centimetres from a wood fire and turn it every ten minutes, for 1½ hours.","Strike the skin: if it sounds hollow and splits, it is ready. Dust with chaat masala and serve with bread and raw onion."]} },

{ id:'buuz-mongol-oulan', c:'as', lat:47.919, lon:106.917, base:6, prep:90, cook:25, diff:2, tags:['lamb','festive','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4f0e6',style:'pastry',food:['#f4f0e6','#e8dcc0','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Khuushuur',en:'Khuushuur'},
  p:{fr:'Oulan-Bator, Mongolie',en:'Ulaanbaatar, Mongolia'},
  d:{fr:"Des chaussons plats de mouton frits dans la graisse, mangés par dizaines pendant le Naadam. On les compte : un homme qui en mange moins de dix pendant les trois jours de fête passe pour peu sérieux.",
     en:"Flat mutton pasties fried in fat, eaten by the dozen during Naadam. They are counted: a man who eats fewer than ten over the three days of festivities is thought unserious."},
  i:[['flour',600,'g'],['water',300,'ml'],['ground_lamb',700,'g'],['lamb_fat',150,'g'],['onion',300,'g'],['garlic',6,'clove'],['caraway',1,'tsp'],['mutton_tallow',600,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez farine, eau et sel en une pâte ferme et laissez-la reposer 40 minutes.","Hachez le mouton et son gras au couteau, mêlez-les à l'oignon très finement haché, à l'ail, au carvi et à un peu d'eau : la farce doit rester humide.","Étalez des disques de 12 cm, déposez une cuillerée de farce, repliez et scellez le bord en le pinçant en pli plat.","Aplatissez chaque chausson à la paume : c'est ce qui les distingue des buuz, cuits à la vapeur.","Faites-les frire 4 minutes par face dans la graisse de mouton à 170 °C, jusqu'à ce qu'ils cloquent et dorent."],
     en:["Knead the flour, water and salt into a firm dough and rest it for 40 minutes.","Chop the mutton and its fat by knife, mix with very finely chopped onion, garlic, caraway and a little water: the filling must stay moist.","Roll 12 cm discs, place a spoonful of filling, fold over and seal the edge with a flat pleat.","Flatten each pasty with the palm: this is what distinguishes them from steamed buuz.","Fry them 4 minutes a side in mutton fat at 170°C, until they blister and turn golden."]} }
,

{ id:'mirza-ghasemi', c:'as', lat:37.280, lon:49.583, base:4, prep:40, cook:45, diff:2, tags:['veg','comfort','fresh'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#5a4a3a','#c9302a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Mirza ghasemi',en:'Mirza ghasemi'},
  p:{fr:'Racht, Gilan, Iran',en:'Rasht, Gilan, Iran'},
  d:{fr:"Des aubergines fumées écrasées à la tomate, à l'ail et à l'œuf. Le plat porte le nom d'un gouverneur du Gilan du XIXe siècle ; c'est la fumée, obtenue en brûlant la peau de l'aubergine à la flamme nue, qui fait toute sa singularité.",
     en:"Smoked aubergines crushed with tomato, garlic and egg. The dish takes its name from a nineteenth-century governor of Gilan; it is the smoke, got by charring the aubergine skin over a naked flame, that makes it what it is."},
  i:[['eggplant',1,'kg'],['ripe_tomato',500,'g'],['garlic',10,'clove'],['egg',4,'pc'],['turmeric',8,'g'],['sunflower_oil',80,'ml'],['flatbread',4,'pc'],['pepper',null,''],['salt',null,'']],
  s:{fr:["Percez les aubergines de quelques coups de fourchette et brûlez-les entières sur la flamme vive, en les tournant jusqu'à ce que la peau soit noire de partout.","Le four ne remplace pas la flamme : sans peau carbonisée, il n'y a pas de fumée, et le mirza ghasemi devient un simple caviar d'aubergine.","Laissez-les tiédir dans un sac fermé, pelez-les et écrasez la chair à la fourchette, jamais au mixeur.","Faites blondir l'ail émincé dans l'huile avec le curcuma, puis ajoutez la tomate concassée et laissez réduire un quart d'heure.","Ajoutez l'aubergine, mêlez à feu doux, puis cassez les œufs et brouillez-les à peine dans la masse. Servez avec du pain plat."],
     en:["Prick the aubergines a few times and char them whole over a fierce flame, turning until the skin is black all over.","An oven will not replace the flame: without charred skin there is no smoke, and mirza ghasemi becomes plain aubergine purée.","Let them cool in a sealed bag, peel them and crush the flesh with a fork, never in a blender.","Soften the sliced garlic in oil with the turmeric, then add the crushed tomato and reduce for a quarter of an hour.","Add the aubergine, fold over low heat, then break in the eggs and barely scramble them through. Serve with flatbread."]} },

{ id:'baghali-ghatogh', c:'as', lat:37.275, lon:49.590, base:4, prep:30, cook:50, diff:2, tags:['legume','comfort','veg'],
  art:{v:'pot',bg:'#28331f',plate:'#f0e4c8',style:'stew',food:['#7fae5a','#4f6f3a','#e8c46a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Baghali ghatogh',en:'Baghali ghatogh'},
  p:{fr:'Racht, Gilan, Iran',en:'Rasht, Gilan, Iran'},
  d:{fr:"Des fèves mijotées à l'aneth et à l'ail, liées à l'œuf. Le Gilan, au bord de la Caspienne, est la province la plus humide d'Iran : sa cuisine est verte et herbacée, à l'opposé des plats safranés du plateau central.",
     en:"Broad beans stewed with dill and garlic, bound with egg. Gilan, on the Caspian shore, is Iran's wettest province: its cooking is green and herbaceous, the opposite of the saffron dishes of the central plateau."},
  i:[['fava_beans',700,'g'],['dill',3,'bunch'],['garlic',12,'clove'],['egg',4,'pc'],['turmeric',8,'g'],['butter',60,'g'],['long_grain_rice',400,'g'],['pepper',null,''],['salt',null,'']],
  s:{fr:["Employez des fèves séchées trempées une nuit, ou des fèves fraîches doublement écossées.","Retirez la peau de chaque fève : c'est long, mais laissée en place elle reste coriace et le plat ne prend jamais sa texture fondante.","Faites revenir l'ail entier, en gousses écrasées mais non hachées, dans le beurre avec le curcuma.","Ajoutez les fèves et de l'eau à hauteur, et laissez mijoter quarante minutes à couvert.","Ajoutez l'aneth ciselé en quantité généreuse, puis cassez les œufs entiers dessus et couvrez cinq minutes sans remuer."],
     en:["Use dried beans soaked overnight, or fresh beans double-podded.","Slip the skin off every bean: it takes time, but left on it stays tough and the dish never reaches its melting texture.","Fry the garlic whole, cloves crushed but not chopped, in butter with the turmeric.","Add the beans and water to cover, and simmer forty minutes covered.","Add generous quantities of chopped dill, then break the whole eggs on top and cover five minutes without stirring."]} },

{ id:'tahchin', c:'as', lat:35.689, lon:51.389, base:8, prep:90, cook:90, diff:3, tags:['rice','poultry','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#e8a032','#e8c46a','#f4f0e6','#7a2a3a'],garnish:'#7fae6a'},
  n:{fr:'Tahchin',en:'Tahchin'},
  p:{fr:'Téhéran, Iran',en:'Tehran, Iran'},
  d:{fr:"Un gâteau de riz au safran et au yaourt, doré et croustillant, démoulé d'un bloc. Il transforme le tahdig — la croûte de riz que tout Iranien se dispute — en plat entier : ici, le fond de la casserole n'est pas un bonus, c'est tout le principe.",
     en:"A saffron and yoghurt rice cake, golden and crisp, turned out in one piece. It turns tahdig — the rice crust every Iranian fights over — into a whole dish: here the bottom of the pot is not a bonus, it is the entire point."},
  i:[['basmati_rice',600,'g'],['plain_yogurt',400,'g'],['egg_yolk',4,'pc'],['saffron',1,'g'],['chicken_thighs',700,'g'],['onion',2,'pc'],['butter',150,'g'],['barberries',80,'g'],['sunflower_oil',80,'ml'],['sugar',30,'g'],['pepper',null,''],['salt',null,'']],
  s:{fr:["Faites tremper le riz deux heures à l'eau salée, puis précuisez-le sept minutes seulement : il doit rester dur au cœur.","Un riz cuit à point à ce stade finira en bouillie après quatre-vingt-dix minutes de four.","Infusez le safran pilé dans deux cuillerées d'eau chaude vingt minutes, puis mêlez au yaourt et aux jaunes.","Mêlez la moitié du riz à cette crème, tassez-la au fond du moule beurré, ajoutez le poulet, puis le reste du riz sans le tasser.","Couvrez d'aluminium serré et cuisez 90 minutes à 180 °C. Démoulez d'un coup sur un plat, croûte vers le haut."],
     en:["Soak the rice two hours in salted water, then parboil it seven minutes only: it must stay hard at the centre.","Rice cooked through at this stage will be porridge after ninety minutes in the oven.","Infuse the ground saffron in two spoonfuls of hot water for twenty minutes, then mix into the yoghurt and yolks.","Fold half the rice into that cream, press it into the buttered dish, add the chicken, then the rest of the rice unpacked.","Cover tightly with foil and bake 90 minutes at 180°C. Turn out in one movement, crust upwards."]} },

{ id:'ash-e-doogh', c:'as', lat:38.080, lon:46.293, base:6, prep:40, cook:60, diff:2, tags:['soup','veg','comfort'],
  art:{v:'bowl',bg:'#28331f',plate:'#f0e4c8',style:'soup',food:['#f4f0e6','#4f6f3a','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Ash-e doogh',en:'Ash-e doogh'},
  p:{fr:'Tabriz, Azerbaïdjan oriental, Iran',en:'Tabriz, East Azerbaijan, Iran'},
  d:{fr:"Une soupe de yaourt aux herbes et aux boulettes, servie chaude ou froide. Le yaourt chauffé tranche si l'on n'y prend garde : les cuisinières d'Azerbaïdjan le stabilisent d'abord à l'œuf et à la farine, et remuent toujours dans le même sens.",
     en:"A yoghurt soup with herbs and meatballs, served hot or cold. Heated yoghurt splits if you are careless: Azerbaijani cooks stabilise it first with egg and flour, and always stir in the same direction."},
  i:[['plain_yogurt',1,'kg'],['egg',2,'pc'],['flour',40,'g'],['chickpeas',150,'g'],['ground_beef',250,'g'],['mint',2,'bunch'],['parsley',1,'bunch'],['cilantro',1,'bunch'],['scallion',1,'bunch'],['onion',2,'pc'],['rice',80,'g'],['turmeric',8,'g'],['butter',60,'g'],['salt',null,'']],
  s:{fr:["Battez le yaourt avec l'œuf et la farine délayée jusqu'à obtenir un mélange parfaitement lisse, avant toute chauffe.","Chauffez très doucement en remuant sans interruption et toujours dans le même sens, un quart d'heure, jusqu'au premier frémissement.","Ce n'est qu'après ce premier frémissement que le yaourt cesse de risquer de trancher, et l'on peut alors cesser de remuer.","Ajoutez les pois chiches cuits, le riz et les boulettes de bœuf grosses comme des noisettes.","Terminez par les herbes en quantité et une menthe séchée frite au beurre, versée en surface au moment de servir."],
     en:["Beat the yoghurt with the egg and slaked flour to a perfectly smooth mixture, before any heat.","Heat very gently, stirring without pause and always in the same direction, a quarter of an hour, until the first tremble.","Only after that first tremble does the yoghurt stop being at risk of splitting, and you may stop stirring.","Add the cooked chickpeas, the rice and hazelnut-sized beef meatballs.","Finish with generous herbs and dried mint fried in butter, poured over as you serve."]} },

{ id:'gheymeh', c:'as', lat:35.700, lon:51.400, base:6, prep:40, cook:100, diff:2, tags:['lamb','stew','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#8f4a3a','#e8a032','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Gheymeh',en:'Gheymeh'},
  p:{fr:'Téhéran, Iran',en:'Tehran, Iran'},
  d:{fr:"Un ragoût d'agneau aux pois cassés jaunes et au citron séché, couvert de frites. C'est le plat que l'on distribue gratuitement pendant le mois de Muharram, cuit dans des marmites de plusieurs centaines de litres et servi à des quartiers entiers.",
     en:"A lamb stew with yellow split peas and dried lime, topped with chips. It is the dish given away free during Muharram, cooked in pots of several hundred litres and served to whole neighbourhoods."},
  i:[['lamb_shoulder',700,'g'],['yellow_peas',200,'g'],['dried_lime',4,'pc'],['tomato_paste',80,'g'],['onion',3,'pc'],['turmeric',10,'g'],['cinnamon',5,'g'],['potato',500,'g'],['saffron',0.5,'g'],['sunflower_oil',100,'ml'],['long_grain_rice',400,'g'],['salt',null,'']],
  s:{fr:["Faites revenir l'oignon longuement, jusqu'à ce qu'il brunisse franchement : c'est lui qui donne la couleur et le fond du ragoût.","Ajoutez le curcuma et laissez-le griller dans l'huile avant la viande, sinon il garde un goût de poudre crue.","Percez les citrons séchés de deux trous et ajoutez-les entiers : entaillés davantage, ils libèrent leur amertume et rendent le plat immangeable.","Faites cuire les pois cassés à part vingt minutes avant de les joindre : cuits dès le début, ils se défont en purée.","Servez couvert de frites en allumettes, préparées à part et posées au dernier moment."],
     en:["Fry the onion at length, until it browns frankly: it gives the stew its colour and its base.","Add the turmeric and let it toast in the oil before the meat, or it keeps a raw powdery taste.","Pierce the dried limes twice and add them whole: cut further, they release their bitterness and make the dish inedible.","Cook the split peas separately for twenty minutes before adding them: in from the start, they collapse into purée.","Serve covered with matchstick chips, made separately and set on at the last moment."]} },

{ id:'sholeh-zard', c:'as', lat:35.694, lon:51.421, base:8, prep:30, cook:120, diff:2, tags:['sweet','slow','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8a032','#e8c46a','#f2dfa8','#7a2a3a'],garnish:'#c9754a'},
  n:{fr:'Sholeh zard',en:'Sholeh zard'},
  p:{fr:'Téhéran, Iran',en:'Tehran, Iran'},
  d:{fr:"Un pudding de riz au safran, à l'eau de rose et à la cardamome, servi froid et décoré. Il se prépare comme nazri, offrande votive distribuée aux voisins pour remercier d'un vœu exaucé, et son décor à la cannelle porte souvent un motif ou un nom.",
     en:"A rice pudding with saffron, rosewater and cardamom, served cold and decorated. It is made as nazri, a votive offering distributed to neighbours in thanks for an answered prayer, and its cinnamon decoration often carries a pattern or a name."},
  i:[['long_grain_rice',300,'g'],['sugar',500,'g'],['saffron',1,'g'],['rose_water',80,'ml'],['cardamom',10,'pc'],['butter',120,'g'],['almonds',80,'g'],['pistachios',80,'g'],['cinnamon',10,'g'],['water',2,'l']],
  s:{fr:["Faites tremper le riz deux heures, puis cuisez-le dans beaucoup d'eau jusqu'à ce que les grains se défassent complètement.","N'ajoutez le sucre qu'une fois le riz totalement éclaté : versé plus tôt, il durcit le grain et la cuisson n'aboutit jamais.","Comptez encore une heure après le sucre, à feu très doux, en remuant régulièrement.","Infusez le safran pilé dans un peu d'eau chaude vingt minutes et ajoutez-le, puis le beurre, la cardamome et l'eau de rose en fin de cuisson.","Versez dans des coupes plates et laissez refroidir. Décorez de cannelle en poudre et de pistaches concassées."],
     en:["Soak the rice two hours, then cook it in plenty of water until the grains break down completely.","Add the sugar only once the rice has fully burst: added earlier, it hardens the grain and the cooking never finishes.","Allow another hour after the sugar, over very low heat, stirring regularly.","Infuse the ground saffron in a little hot water for twenty minutes and add it, then the butter, cardamom and rosewater at the end.","Pour into shallow bowls and cool. Decorate with ground cinnamon and crushed pistachios."]} },

{ id:'bastani-sonnati', c:'as', lat:32.654, lon:51.668, base:8, prep:60, cook:30, diff:3, tags:['sweet','fresh','festive'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f2dfa8','#f4f0e6','#7fae5a','#e8a032'],garnish:'#7fae6a'},
  n:{fr:'Bastani sonnati',en:'Bastani sonnati'},
  p:{fr:'Ispahan, Iran',en:'Isfahan, Iran'},
  d:{fr:"Une glace au safran et à l'eau de rose, parsemée de pistaches et de copeaux de crème gelée. Sa texture élastique vient du salep, farine d'orchidée sauvage : elle s'étire à la cuillère et fond bien plus lentement qu'une glace ordinaire.",
     en:"A saffron and rosewater ice cream studded with pistachios and shards of frozen cream. Its stretchy texture comes from salep, wild orchid flour: it pulls on the spoon and melts far more slowly than an ordinary ice cream."},
  i:[['whole_milk',1,'l'],['heavy_cream',400,'ml'],['sugar',250,'g'],['saffron',1,'g'],['rose_water',60,'ml'],['salep',20,'g'],['pistachios',100,'g'],['egg_yolk',4,'pc']],
  s:{fr:["Délayez le salep dans le lait froid avant toute chauffe : versé dans le chaud, il forme des grumeaux que rien ne dissout ensuite.","Chauffez doucement en fouettant jusqu'à ce que le mélange épaississe visiblement, une bonne quinzaine de minutes.","Infusez le safran séparément et ajoutez-le hors du feu, avec l'eau de rose — la chaleur emporte leurs parfums.","Étalez de la crème épaisse sur une plaque et congelez-la à part, puis brisez-la en copeaux.","Turbinez la glace et incorporez copeaux et pistaches à la fin. Le salep rend la texture volontairement filante, ce n'est pas un défaut."],
     en:["Slake the salep in cold milk before any heat: poured into hot liquid it lumps in a way nothing later dissolves.","Heat gently, whisking, until the mixture visibly thickens, a good fifteen minutes.","Infuse the saffron separately and add it off the heat with the rosewater — heat carries off their aromas.","Spread thick cream on a tray and freeze it separately, then break it into shards.","Churn the ice cream and fold in the shards and pistachios at the end. Salep makes the texture deliberately stretchy, which is not a fault."]} },

{ id:'gaz', c:'as', lat:32.660, lon:51.680, base:12, prep:60, cook:40, diff:3, tags:['sweet','slow','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#7fae5a','#f0e8d0','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Gaz',en:'Gaz'},
  p:{fr:'Ispahan, Iran',en:'Isfahan, Iran'},
  d:{fr:"Un nougat blanc aux pistaches, parfumé à l'eau de rose. Le gaz authentique est fait de la manne du tamaris, une sève sucrée que l'insecte fait suinter des branches dans les montagnes du Zagros ; elle se récolte à la main et le sucre ne la remplace qu'imparfaitement.",
     en:"A white nougat with pistachios, scented with rosewater. Genuine gaz is made from tamarisk manna, a sweet sap an insect makes weep from the branches in the Zagros mountains; it is gathered by hand, and sugar replaces it only imperfectly."},
  i:[['sugar',600,'g'],['glucose_syrup',200,'g'],['egg_white',2,'pc'],['pistachios',250,'g'],['rose_water',40,'ml'],['water',200,'ml'],['cornstarch',60,'g'],['powdered_sugar',80,'g']],
  s:{fr:["Portez le sucre, le glucose et l'eau à 140 °C au thermomètre, sans jamais remuer une fois l'ébullition atteinte.","Montez les blancs en neige ferme pendant la cuisson du sirop : ils doivent être prêts au moment exact où il atteint la température.","Versez le sirop en filet mince sur les blancs en fouettant sans arrêt, le long de la paroi et non sur le fouet.","Continuez de fouetter dix minutes, jusqu'à ce que la masse devienne très ferme et perde son brillant.","Incorporez les pistaches et l'eau de rose, étalez entre deux feuilles saupoudrées de fécule et laissez sécher douze heures."],
     en:["Bring the sugar, glucose and water to 140°C on a thermometer, never stirring once it boils.","Whip the whites to firm peaks while the syrup cooks: they must be ready at the exact moment it reaches temperature.","Pour the syrup in a thin stream onto the whites, whisking without pause, down the side of the bowl and not onto the whisk.","Keep whisking ten minutes, until the mass turns very firm and loses its gloss.","Fold in the pistachios and rosewater, spread between two starch-dusted sheets and dry twelve hours."]} },

{ id:'nan-e-berenji', c:'as', lat:36.279, lon:50.004, base:10, prep:120, cook:20, diff:2, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#f2dfa8','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Nan-e berenji',en:'Nan-e berenji'},
  p:{fr:'Qazvin, Iran',en:'Qazvin, Iran'},
  d:{fr:"Des sablés de farine de riz à la cardamome, si friables qu'ils fondent en bouche. Ils ne contiennent aucune farine de blé : sans gluten, la pâte ne tient que par la graisse, et le moindre excès de manipulation la fait s'effriter avant cuisson.",
     en:"Rice flour shortbreads with cardamom, so short they dissolve in the mouth. They contain no wheat flour at all: with no gluten the dough holds only through fat, and the slightest overhandling crumbles it before baking."},
  i:[['rice_flour',400,'g'],['powdered_sugar',200,'g'],['clarified_butter',250,'g'],['egg_yolk',2,'pc'],['cardamom',15,'g'],['rose_water',40,'ml'],['poppy_seed',20,'g']],
  s:{fr:["Battez le beurre clarifié et le sucre glace vingt minutes, jusqu'à ce que le mélange blanchisse et triple de volume.","Ce battage prolongé est ce qui remplace le gluten : il incorpore l'air qui donnera la friabilité.","Incorporez les jaunes, l'eau de rose et la cardamome moulue, puis la farine de riz en une seule fois, à la spatule.","Laissez reposer la pâte deux heures au frais avant de former les disques, sans jamais la pétrir.","Marquez d'un motif à la fourchette, parsemez de pavot et cuisez 15 minutes à 160 °C. Ils doivent rester blancs, sans coloration."],
     en:["Beat the clarified butter and icing sugar for twenty minutes, until the mixture pales and triples in volume.","That long beating is what replaces the gluten: it works in the air that will give the shortness.","Beat in the yolks, rosewater and ground cardamom, then the rice flour all at once, with a spatula.","Rest the dough two hours in the cold before shaping the discs, never kneading it.","Mark a pattern with a fork, scatter poppy seeds and bake 15 minutes at 160°C. They must stay white, without colouring."]} }
,

{ id:'shir-berenj', c:'as', lat:35.715, lon:51.404, base:6, prep:20, cook:60, diff:1, tags:['sweet','breakfast','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#f0e8d0','#e8dcb8','#7a2a3a'],garnish:'#c9754a'},
  n:{fr:'Shir berenj',en:'Shir berenj'},
  p:{fr:'Téhéran, Iran',en:'Tehran, Iran'},
  d:{fr:"Un riz au lait non sucré, servi avec de la confiture ou du sirop à part. Contrairement au sholeh zard, il ne contient ni safran ni sucre : c'est un petit-déjeuner d'hiver, et chacun le sucre lui-même dans son bol.",
     en:"An unsweetened rice pudding served with jam or syrup on the side. Unlike sholeh zard it holds neither saffron nor sugar: it is a winter breakfast, and each person sweetens their own bowl."},
  i:[['long_grain_rice',250,'g'],['whole_milk',1.5,'l'],['rose_water',30,'ml'],['cardamom',6,'pc'],['cherry_jam',200,'g'],['pistachios',60,'g'],['salt',null,'']],
  s:{fr:["Cuisez d'abord le riz à l'eau, quinze minutes, jusqu'à ce qu'il ait absorbé toute l'eau et commence à s'ouvrir.","Ajoutez ensuite le lait chaud en trois fois, en attendant chaque fois qu'il soit absorbé avant la suivante.","Versé d'un coup, le lait empêche l'amidon de se libérer et le riz reste en grains distincts au lieu de devenir crémeux.","Comptez quarante-cinq minutes à feu très doux, en remuant toutes les cinq minutes.","Parfumez à l'eau de rose et à la cardamome hors du feu. Servez tiède, avec de la confiture de cerises noires à côté."],
     en:["Cook the rice in water first, fifteen minutes, until it has absorbed all the water and begins to split.","Then add hot milk in three additions, waiting each time for it to be absorbed before the next.","Poured in at once, the milk stops the starch releasing and the rice stays in separate grains instead of turning creamy.","Allow forty-five minutes over very low heat, stirring every five minutes.","Scent with rosewater and cardamom off the heat. Serve warm, with black cherry jam alongside."]} },

{ id:'dizi', c:'as', lat:35.680, lon:51.420, base:4, prep:720, cook:240, diff:2, tags:['lamb','slow','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#e8c46a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Dizi',en:'Dizi'},
  p:{fr:'Téhéran, Iran',en:'Tehran, Iran'},
  d:{fr:"Un ragoût d'agneau et de pois chiches cuit en pot de pierre, mangé en deux services. On boit d'abord le bouillon avec du pain émietté, puis on écrase le solide au pilon pour en faire une pâte : le même plat fournit une soupe et un plat de résistance.",
     en:"A lamb and chickpea stew cooked in a stone pot, eaten in two courses. First the broth is drunk with torn bread, then the solids are pounded to a paste: one dish provides both a soup and a main course."},
  i:[['lamb_shank',800,'g'],['chickpeas',200,'g'],['white_beans',150,'g'],['potato',400,'g'],['onion',2,'pc'],['tomato_paste',60,'g'],['dried_lime',3,'pc'],['turmeric',10,'g'],['lamb_fat',80,'g'],['flatbread',6,'pc'],['salt',null,'']],
  s:{fr:["Faites tremper pois chiches et haricots blancs douze heures, en changeant l'eau deux fois.","Réunissez tout dans un pot de terre ou de pierre et couvrez d'eau froide, sans saler.","Cuisez quatre heures à feu très doux, ou trois heures au four à 150 °C : le pot doit à peine frémir.","Salez seulement à la troisième heure — le sel précoce empêche les légumineuses de s'attendrir.","Filtrez le bouillon dans un bol, écrasez le reste au pilon jusqu'à obtenir une pâte homogène, et servez les deux ensemble."],
     en:["Soak the chickpeas and white beans twelve hours, changing the water twice.","Put everything in a clay or stone pot and cover with cold water, without salting.","Cook four hours over very low heat, or three hours in a 150°C oven: the pot should barely tremble.","Salt only in the third hour — early salt stops the pulses softening.","Strain the broth into a bowl, pound the solids to a smooth paste, and serve the two together."]} },

{ id:'mahi-shekam-por', c:'as', lat:36.563, lon:53.060, base:4, prep:60, cook:50, diff:3, tags:['sea','bake','festive'],
  art:{v:'plate',bg:'#2c3440',plate:'#f0e4c8',style:'fish',food:['#8f5a3a','#e8c46a','#7a2a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Mahi shekam por',en:'Mahi shekam por'},
  p:{fr:'Sari, Mazandéran, Iran',en:'Sari, Mazandaran, Iran'},
  d:{fr:"Un poisson entier farci d'herbes, de noix et de mélasse de grenade, rôti au four. C'est le plat de Nowrouz sur la côte caspienne : le poisson y remplace l'agneau du plateau, et la farce aigre-douce y est la même que celle du fesenjan.",
     en:"A whole fish stuffed with herbs, walnuts and pomegranate molasses, roasted. It is the Nowruz dish of the Caspian coast: fish replaces the lamb of the plateau, and the sweet-sour stuffing is the same as fesenjan's."},
  i:[['whole_fish',1.5,'kg'],['walnuts',200,'g'],['pomegranate_molasses',80,'ml'],['barberries',60,'g'],['cilantro',2,'bunch'],['parsley',1,'bunch'],['onion',2,'pc'],['garlic',6,'clove'],['turmeric',8,'g'],['saffron',0.5,'g'],['sunflower_oil',80,'ml'],['lime',2,'pc'],['salt',null,'']],
  s:{fr:["Videz le poisson par les ouïes plutôt que par le ventre, si vous savez le faire : la farce tient bien mieux dans une cavité fermée.","Sinon, fendez le ventre et prévoyez de le recoudre au fil de cuisine.","Hachez les noix grossièrement et faites-les griller à sec : crues, elles rendent la farce pâteuse et légèrement amère.","Faites revenir oignon, ail et herbes, ajoutez noix, épine-vinette et mélasse de grenade, et laissez refroidir avant de farcir.","Rôtissez 45 minutes à 190 °C en arrosant d'huile safranée toutes les quinze minutes."],
     en:["Gut the fish through the gills rather than the belly if you can: the stuffing holds far better in a closed cavity.","Otherwise slit the belly and plan to sew it up with kitchen thread.","Chop the walnuts roughly and dry-toast them: raw, they make the stuffing pasty and faintly bitter.","Fry the onion, garlic and herbs, add the walnuts, barberries and pomegranate molasses, and cool before stuffing.","Roast 45 minutes at 190°C, basting with saffron oil every fifteen minutes."]} },

{ id:'ash-e-shalgham', c:'as', lat:38.070, lon:46.300, base:6, prep:40, cook:90, diff:2, tags:['soup','veg','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#f2dfa8','#4f6f3a','#e8c46a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Ash-e shalgham',en:'Ash-e shalgham'},
  p:{fr:'Tabriz, Iran',en:'Tabriz, Iran'},
  d:{fr:"Une soupe épaisse au navet, aux légumineuses et aux herbes, réputée contre le rhume. En Iran le navet est considéré comme un aliment « chaud » selon la classification humorale héritée de la médecine gréco-arabe, et l'on en mange l'hiver pour cette raison précise.",
     en:"A thick soup of turnip, pulses and herbs, held to be good against colds. In Iran turnip is classed as a warm food under the humoral system inherited from Greco-Arabic medicine, and it is eaten in winter for exactly that reason."},
  i:[['turnip',800,'g'],['chickpeas',150,'g'],['lentils',150,'g'],['white_beans',100,'g'],['rice',80,'g'],['spinach',300,'g'],['parsley',1,'bunch'],['cilantro',1,'bunch'],['onion',3,'pc'],['turmeric',10,'g'],['mint',30,'g'],['sour_whey',150,'ml'],['salt',null,'']],
  s:{fr:["Faites tremper les légumineuses une nuit et cuisez-les séparément : elles n'ont pas le même temps de cuisson, et ensemble certaines se défont pendant que d'autres restent dures.","Faites brunir les oignons émincés longuement dans l'huile, jusqu'à ce qu'ils soient franchement colorés.","Ajoutez le curcuma, puis les navets en gros dés, et laissez-les prendre couleur avant de mouiller.","Réunissez légumineuses, riz et navets et laissez mijoter quarante minutes, jusqu'à ce que la soupe épaississe d'elle-même.","Ajoutez les herbes en fin de cuisson et servez avec du kashk et une menthe séchée frite à l'huile."],
     en:["Soak the pulses overnight and cook them separately: they do not share a cooking time, and together some collapse while others stay hard.","Brown the sliced onions at length in oil, until frankly coloured.","Add the turmeric, then the turnips in large dice, and let them take colour before moistening.","Bring pulses, rice and turnips together and simmer forty minutes, until the soup thickens by itself.","Add the herbs at the end and serve with kashk and dried mint fried in oil."]} },

{ id:'kotlet', c:'as', lat:35.705, lon:51.395, base:6, prep:60, cook:25, diff:2, tags:['beef','fry','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#c9924a','#8f5a3a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Kotlet',en:'Kotlet'},
  p:{fr:'Téhéran, Iran',en:'Tehran, Iran'},
  d:{fr:"Des galettes plates de viande hachée et de pomme de terre râpée, frites. Elles sont arrivées d'Europe au début du XXe siècle avec le mot lui-même ; en Iran elles se mangent froides, glissées dans du pain, et c'est le repas de voyage par excellence.",
     en:"Flat patties of minced meat and grated potato, fried. They arrived from Europe in the early twentieth century along with the word itself; in Iran they are eaten cold, tucked into bread, and are the travelling meal par excellence."},
  i:[['ground_beef',500,'g'],['potato',400,'g'],['onion',2,'pc'],['egg',2,'pc'],['turmeric',10,'g'],['breadcrumbs',80,'g'],['sunflower_oil',300,'ml'],['flatbread',6,'pc'],['tomato',2,'pc'],['pickles',150,'g'],['pepper',null,''],['salt',null,'']],
  s:{fr:["Râpez la pomme de terre crue et l'oignon, puis pressez-les dans un linge jusqu'à en extraire toute l'eau.","Cette eau est la cause de tous les échecs : une pâte humide se disloque dans l'huile et la galette se défait.","Travaillez la viande et les légumes râpés dix minutes à la main, jusqu'à ce que la masse devienne homogène et collante.","Laissez reposer une heure au frais, puis formez des galettes ovales très plates, d'un centimètre au plus.","Frites à feu moyen dans deux centimètres d'huile, quatre minutes par face. Se mangent chaudes ou froides, avec du pain et des cornichons."],
     en:["Grate the raw potato and onion, then wring them in a cloth until all the water is out.","That water causes every failure: a wet mixture disintegrates in the oil and the patty falls apart.","Work the meat and grated vegetables by hand for ten minutes, until the mass turns even and tacky.","Rest an hour in the cold, then shape very flat oval patties, a centimetre at most.","Fry over medium heat in two centimetres of oil, four minutes a side. Eaten hot or cold, with bread and pickles."]} },

{ id:'noon-e-sangak', c:'as', lat:35.688, lon:51.410, base:6, prep:1440, cook:15, diff:3, tags:['bread','bake','slow'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#c9924a','#e8c46a','#f2dfa8','#8f7a5a'],garnish:'#7fae6a'},
  n:{fr:'Noon-e sangak',en:'Noon-e sangak'},
  p:{fr:'Téhéran, Iran',en:'Tehran, Iran'},
  d:{fr:"Un grand pain plat au levain cuit directement sur un lit de galets brûlants. Sangak veut dire « petit caillou » : la pâte est jetée sur les pierres, qui laissent leurs empreintes creuses dans la mie, et il faut secouer le pain à la sortie pour les faire tomber.",
     en:"A large sourdough flatbread baked directly on a bed of scalding pebbles. Sangak means little pebble: the dough is thrown onto the stones, which leave hollow prints in the crumb, and the loaf must be shaken on leaving the oven to make them fall out."},
  i:[['whole_wheat_flour',800,'g'],['sourdough_starter',200,'g'],['water',600,'ml'],['sesame_seeds',40,'g'],['poppy_seed',20,'g'],['salt',null,'']],
  s:{fr:["Employez une farine complète et une hydratation très forte, autour de 75 % : la pâte doit être franchement collante.","Laissez fermenter douze heures au levain, à température ambiante, jusqu'à ce qu'elle triple et sente l'acide.","Chauffez un lit de galets propres au four à 280 °C pendant une heure au moins — les pierres doivent être brûlantes de part en part.","Étalez la pâte à la main directement sur les galets, en un ovale allongé, et parsemez de graines.","Dix minutes suffisent. Secouez le pain à la sortie pour faire tomber les cailloux, et n'oubliez jamais de vérifier avant de mordre."],
     en:["Use wholemeal flour and very high hydration, around 75%: the dough must be frankly sticky.","Ferment twelve hours with sourdough at room temperature, until it triples and smells sour.","Heat a bed of clean pebbles in a 280°C oven for at least an hour — the stones must be scalding through.","Spread the dough by hand directly onto the pebbles, in a long oval, and scatter with seeds.","Ten minutes is enough. Shake the loaf on removal to knock out the stones, and never forget to check before biting."]} },

{ id:'doogh', c:'as', lat:35.692, lon:51.386, base:6, prep:15, cook:0, diff:1, tags:['drink','fresh','fast'],
  art:{v:'glass',bg:'#33291f',plate:'#f4ead4',style:'drink',food:['#f4f0e6','#f0e8d0','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Doogh',en:'Doogh'},
  p:{fr:'Téhéran, Iran',en:'Tehran, Iran'},
  d:{fr:"Une boisson de yaourt salée à la menthe, souvent légèrement gazeuse. Le doogh traditionnel fermente quelques jours et pétille tout seul ; la version industrielle ajoute du gaz, ce que les Iraniens distinguent immédiatement au goût.",
     en:"A salted yoghurt drink with mint, often lightly sparkling. Traditional doogh ferments a few days and fizzes by itself; the industrial version adds gas, which Iranians tell apart at once by taste."},
  i:[['plain_yogurt',600,'g'],['water',900,'ml'],['mint',20,'g'],['dried_rose_petals',5,'g'],['salt',null,'']],
  s:{fr:["Employez un yaourt nature entier et bien acide : un yaourt doux donne une boisson fade que le sel ne rattrape pas.","Fouettez-le d'abord seul jusqu'à ce qu'il soit parfaitement lisse, avant d'ajouter la moindre eau.","Ajoutez l'eau glacée peu à peu, en fouettant : versée d'un coup, elle laisse des grumeaux de yaourt en suspension.","Salez franchement — le doogh est une boisson salée, et un dosage timide le rend insipide.","Ajoutez la menthe séchée écrasée entre les doigts et les pétales de rose, et laissez reposer une heure au frais."],
     en:["Use a full-fat plain yoghurt with a good sourness: a mild yoghurt gives a flat drink that salt will not rescue.","Whisk it alone first until perfectly smooth, before adding any water.","Add iced water little by little, whisking: poured in at once it leaves lumps of yoghurt suspended.","Salt frankly — doogh is a salted drink, and a timid hand makes it insipid.","Add dried mint crushed between the fingers and rose petals, and rest an hour in the cold."]} },

{ id:'chai-irani', c:'as', lat:38.075, lon:46.290, base:6, prep:10, cook:25, diff:2, tags:['drink','comfort','slow'],
  art:{v:'glass',bg:'#33291f',plate:'#f4ead4',style:'drink',food:['#8f4a3a','#c9754a','#e8c46a','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Chai iranien',en:'Iranian chai'},
  p:{fr:'Tabriz, Iran',en:'Tabriz, Iran'},
  d:{fr:"Un thé noir infusé au samovar, servi dans un verre étroit et bu à travers un morceau de sucre. Le sucre ne se met pas dans le verre : on le tient entre les dents et le thé passe au travers, ce qui permet de doser soi-même à chaque gorgée.",
     en:"Black tea brewed on a samovar, served in a narrow glass and drunk through a lump of sugar. The sugar does not go in the glass: it is held between the teeth and the tea passes through it, letting each sip be sweetened to taste."},
  i:[['black_tea',30,'g'],['water',2,'l'],['cardamom',6,'pc'],['dried_rose_petals',5,'g'],['sugar_cubes',100,'g']],
  s:{fr:["Faites bouillir l'eau dans le corps du samovar et ébouillantez la théière posée dessus avant d'y mettre le thé.","Mettez le thé dans la théière avec la cardamome et un peu d'eau bouillante seulement, pour former un concentré très fort.","Laissez ce concentré infuser vingt minutes sur le samovar, à la chaleur de la vapeur et jamais sur une flamme directe.","Servez en versant un fond de concentré dans le verre et en allongeant à l'eau bouillante, selon la force voulue.","Le thé doit être d'un rouge acajou et parfaitement translucide. Trouble, il a bouilli et devient amer."],
     en:["Boil the water in the samovar body and scald the teapot standing on it before adding the tea.","Put the tea in the pot with the cardamom and only a little boiling water, to make a very strong concentrate.","Let that concentrate steep twenty minutes on the samovar, in the steam's heat and never over a direct flame.","Serve by pouring a little concentrate into the glass and lengthening it with boiling water, to the strength wanted.","The tea should be mahogany red and perfectly translucent. Cloudy, it has boiled and turns bitter."]} }
];
